'use client';

import { useLayoutEffect, useRef, type ReactNode } from 'react';
import { cx } from '@/utils/cx';

const layoutProperties = new Set([
  'height', 'block-size', 'min-height', 'max-height', 'min-block-size', 'max-block-size',
  'width', 'inline-size', 'min-width', 'max-width', 'min-inline-size', 'max-inline-size',
  'padding-top', 'padding-bottom', 'padding-left', 'padding-right', 'padding-block-start', 'padding-block-end',
  'margin-top', 'margin-bottom', 'margin-left', 'margin-right', 'margin-block-start', 'margin-block-end',
  'border-top-width', 'border-bottom-width', 'gap', 'row-gap', 'column-gap', 'grid-template-rows', 'grid-template-columns', 'flex-basis', 'font-size', 'line-height', 'letter-spacing',
]);

/** Animate real layout height so adjacent content follows without being scaled. */
export function AnimatedHeight({ children, className }: { children: ReactNode; className?: string }) {
  const frameRef = useRef<HTMLDivElement>(null);
  const contentRef = useRef<HTMLDivElement>(null);
  useLayoutEffect(() => {
    const frame = frameRef.current;
    const content = contentRef.current;
    if (!frame || !content) return;
    // Start at the natural size, including when server-rendered content is nonempty.
    frame.style.transition = 'none';
    frame.style.height = `${content.offsetHeight}px`;
    void frame.offsetHeight;
    frame.style.removeProperty('transition');
    let alive = true;
    const observed = new WeakSet<Animation>();
    const affectsLayout = (animation: Animation) => {
      if (animation.playState !== 'running') return false;
      if ('transitionProperty' in animation) return layoutProperties.has(String(animation.transitionProperty));
      return animation.effect instanceof KeyframeEffect && animation.effect.getKeyframes().some(frame =>
        Object.keys(frame).some(property => layoutProperties.has(property.replace(/[A-Z]/g, letter => `-${letter.toLowerCase()}`)))
      );
    };
    const nestedLayoutIsMoving = () => content.getAnimations({subtree: true}).some(affectsLayout);
    const restore = () => { if (alive && !nestedLayoutIsMoving()) frame.style.removeProperty('transition'); };
    const observeMotion = () => {
      const moving = content.getAnimations({subtree: true}).filter(affectsLayout);
      for (const animation of moving) if (!observed.has(animation)) {
        observed.add(animation);
        animation.finished.then(restore, restore);
      }
      return moving.length > 0;
    };
    const restoreTransition = (event: TransitionEvent) => {
      if (layoutProperties.has(event.propertyName)) restore();
    };
    content.addEventListener('transitionend', restoreTransition);
    content.addEventListener('transitioncancel', restoreTransition);
    const observer = new ResizeObserver(([entry]) => {
      const height = entry.borderBoxSize?.[0]?.blockSize ?? content.offsetHeight;
      // A child can already be animating its real height. Follow that geometry
      // directly, so nested frames do not each add another full transition.
      const following = observeMotion();
      if (following) frame.style.transition = 'none';
      else frame.style.removeProperty('transition');
      frame.style.height = `${height}px`;
    });
    // Helper text and disclosure spacing can change without changing the
    // content box. Observe the same border box that supplies the target height.
    observer.observe(content, { box: 'border-box' });
    return () => {
      alive = false;
      observer.disconnect();
      content.removeEventListener('transitionend', restoreTransition);
      content.removeEventListener('transitioncancel', restoreTransition);
    };
  }, []);
  return <div ref={frameRef} className={cx('ui-animated-height', className)}><div ref={contentRef} className="ui-animated-height__content">{children}</div></div>;
}

'use client';

import {useMemo,useRef,type AnchorHTMLAttributes,type ButtonHTMLAttributes,type Ref} from 'react';
import {mergeRefs} from 'react-aria';
import {useMotionTokens} from '@/hooks/use-motion-tokens';
import { Button as AriaButton, ProgressBar as AriaProgressBar, type ButtonProps as AriaButtonProps } from 'react-aria-components';
import { AnimatePresence, motion } from 'motion/react';
import { useMediaQuery } from '@/hooks/use-media-query';
import { Spinner } from '@/components/base/spinner/spinner';
import type { IconComponent } from '@/components/foundations/icon-types';
import { cx } from '@/utils/cx';

export type IconButtonSize = 'medium' | 'small' | 'xs';

export type IconButtonProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'children' | 'aria-label' | 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick'> & Pick<AriaButtonProps, 'onFocus' | 'onBlur' | 'onKeyDown' | 'onKeyUp' | 'onClick' | 'isPending' | 'preventFocusOnPress'> & {
  icon: IconComponent;
  /** Animate a glyph change without moving or remounting its button. */
  iconKey?: string | number;
  pendingLabel?: string;
  size?: IconButtonSize;
  variant?: 'secondary' | 'ghost';
  badge?: number;
  ref?: Ref<HTMLButtonElement>;
  'aria-label': string;
};

export type IconLinkButtonProps = Omit<AnchorHTMLAttributes<HTMLAnchorElement>, 'children' | 'aria-label'> & {
  icon: IconComponent;
  size?: IconButtonSize;
  'aria-label': string;
};

export function IconButton({ icon: Icon, iconKey, pendingLabel = 'Working', isPending, size = 'medium', variant = 'secondary', badge, className, type = 'button', disabled, value, ref, ...props }: IconButtonProps) {
  const reducedMotion = useMediaQuery('(prefers-reduced-motion: reduce)');
  const root=useRef<HTMLButtonElement>(null),composed=useMemo(()=>mergeRefs(root,ref),[ref]),tokens=useMotionTokens(root);
  return <AriaButton {...props} ref={composed} type={type} value={value === undefined ? undefined : String(value)} isDisabled={disabled} isPending={isPending} data-size={size} data-variant={variant} className={cx('ui-icon-button', className)}>{iconKey === undefined ? <Icon className="ui-icon-button__icon" aria-hidden /> : <span className="ui-icon-button__glyph" aria-hidden><AnimatePresence initial={false}><motion.span key={iconKey} data-icon-key={iconKey} initial={reducedMotion ? false : { opacity: 0, scale: .65, y: 2 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={reducedMotion ? { opacity: 0 } : { opacity: 0, scale: .65, y: -2 }} transition={{ duration: reducedMotion ? 0 : tokens.fast, ease: tokens.ease }}><Icon className="ui-icon-button__icon"/></motion.span></AnimatePresence></span>}<span className="ui-icon-button__pending" aria-hidden><Spinner size={size === 'medium' ? 'md' : 'sm'}/></span>{isPending && <AriaProgressBar aria-label={pendingLabel} isIndeterminate className="sr-only"/>}{badge !== undefined && badge > 0 && <span className="ui-icon-button__badge" aria-hidden>{badge > 99 ? '99+' : badge}</span>}</AriaButton>;
}

export function IconLinkButton({ icon: Icon, size = 'medium', className, ...props }: IconLinkButtonProps) {
  return <a data-size={size} className={cx('ui-icon-button', className)} {...props}><Icon className="ui-icon-button__icon" aria-hidden /></a>;
}

'use client';

import { createContext, useContext, useLayoutEffect, useRef, useState } from 'react';
import type { ComponentProps, ReactNode } from 'react';
import { Button as AriaButton, Dialog, DialogTrigger, Popover } from 'react-aria-components';
import { cx } from '@/utils/cx';
import { IconButton, type IconButtonProps } from '@/components/base/buttons/icon-button';

const DropdownContext = createContext<{ close: () => void; isOpen: boolean } | null>(null);

export interface DropdownProps {
  isOpen?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (isOpen: boolean) => void;
  children: ReactNode;
}

export function Dropdown({ isOpen, defaultOpen = false, onOpenChange, children }: DropdownProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const open = isOpen === undefined ? internalOpen : isOpen;
  function setOpen(next: boolean) {
    if (isOpen === undefined) setInternalOpen(next);
    onOpenChange?.(next);
  }
  return <DropdownContext.Provider value={{ close: () => setOpen(false), isOpen: open }}><DialogTrigger isOpen={open} onOpenChange={setOpen}>{children}</DialogTrigger></DropdownContext.Provider>;
}

export type DropdownTriggerProps = Omit<ComponentProps<typeof AriaButton>, 'className'> & { className?: string };
export function DropdownTrigger({ className, ...props }: DropdownTriggerProps) {
  return <AriaButton {...props} className={cx('ui-dropdown-trigger', className)} />;
}

// Icon triggers use the same dimensions as every other icon button.
export function DropdownIconTrigger(props: IconButtonProps) {
  return <IconButton {...props} />;
}

export interface DropdownPopoverProps {
  'aria-label': string;
  placement?: ComponentProps<typeof Popover>['placement'];
  triggerRef?: ComponentProps<typeof Popover>['triggerRef'];
  isOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  offset?: number;
  className?: string;
  children: ReactNode;
}

export function DropdownPopover({ 'aria-label': ariaLabel, placement = 'bottom start', triggerRef, isOpen, onOpenChange, offset = 5, className, children }: DropdownPopoverProps) {
  const context = useContext(DropdownContext);
  const open = isOpen ?? context?.isOpen;
  const dialogRef = useRef<HTMLElement>(null);
  useLayoutEffect(() => {
    if (!open) return;
    // An interrupted exit keeps the popover mounted, so its focus scope does
    // not mount again. Restore focus inside on every opening, including reopens.
    const frame = requestAnimationFrame(() => {
      const dialog = dialogRef.current;
      if (dialog && (!dialog.contains(document.activeElement) || document.activeElement === dialog)) {
        (dialog.querySelector<HTMLElement>('[role="menuitem"]:not(:disabled), input:not([disabled]), textarea:not([disabled])') ?? dialog).focus({ preventScroll: true });
      }
    });
    return () => cancelAnimationFrame(frame);
  }, [open]);
  return <Popover placement={placement} data-align={placement.split(' ')[1] ?? 'center'} triggerRef={triggerRef} isOpen={isOpen} onOpenChange={onOpenChange} offset={offset} className={cx('ui-dropdown-popover', className)}>{({isExiting})=><div className="ui-dropdown-content" onKeyDown={event => {
    if (!['ArrowDown', 'ArrowUp', 'Home', 'End'].includes(event.key)) return;
    // Native text/range controls keep their own navigation keys.
    if (event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement) return;
    const items = Array.from(event.currentTarget.querySelectorAll<HTMLButtonElement>('.ui-dropdown-item:not(:disabled), [role="menuitem"]:not(:disabled)'));
    if (!items.length) return;
    event.preventDefault();
    const active = items.indexOf(document.activeElement as HTMLButtonElement);
    const next = event.key === 'Home' ? 0 : event.key === 'End' ? items.length - 1 : event.key === 'ArrowDown' ? (active + 1) % items.length : (active - 1 + items.length) % items.length;
    items[next].focus();
  }}><Dialog inert={isExiting} ref={dialogRef} aria-label={ariaLabel} className="ui-dropdown-dialog"><div>{children}</div></Dialog></div>}</Popover>;
}

export function DropdownGroup({ label, children, className }: { label?: string; children: ReactNode; className?: string }) {
  return <div className={cx('ui-dropdown-group', className)}>{label && <span className="ui-dropdown-group__label">{label}</span>}<div className="ui-dropdown-group__items">{children}</div></div>;
}

export interface DropdownItemProps {
  selected?: boolean;
  isDisabled?: boolean;
  closeOnSelect?: boolean;
  onSelect?: () => void;
  className?: string;
  children: ReactNode;
}

export function DropdownItem({ selected, isDisabled, closeOnSelect = true, onSelect, className, children }: DropdownItemProps) {
  const context = useContext(DropdownContext);
  return <button type="button" disabled={isDisabled} aria-pressed={selected || undefined} className={cx('ui-dropdown-item', className)} onClick={() => { onSelect?.(); if (closeOnSelect) context?.close(); }}>{children}</button>;
}

export function DropdownDivider({ className }: { className?: string }) {
  return <div role="separator" aria-orientation="horizontal" className={cx('ui-dropdown-divider', className)} />;
}

import type { CSSProperties } from 'react';
import { cx } from '@/utils/cx';

export type SpinnerProps = {
  size?: 'xs' | 'sm' | 'md' | 'lg';
  label?: string;
  className?: string;
  style?: CSSProperties;
};

/** Omit the label when a containing busy control already names the operation. */
export function Spinner({ size = 'md', label, className, style }: SpinnerProps) {
  return <span className={cx('ui-spinner', className)} data-size={size} role={label ? 'status' : undefined} aria-label={label} aria-hidden={!label || undefined} style={style}>
    <svg viewBox="0 0 24 24" fill="none" aria-hidden><circle cx="12" cy="12" r="9" stroke="currentColor" strokeWidth="2" opacity=".18"/><path d="M12 3a9 9 0 0 1 9 9" stroke="currentColor" strokeWidth="2" strokeLinecap="round"/></svg>
  </span>;
}

'use client';

import { useEffect, useState } from 'react';
import { cx } from '@/utils/cx';

export type AgentThinkingProps = {
  variant?: 'wave' | 'spin' | 'stars' | 'infinity' | 'orb';
  label?: string;
  active?: boolean;
  showTimer?: boolean;
  shimmer?: boolean;
  tone?: 'subtle' | 'accent';
  className?: string;
};

const orbitOrder = [0, 1, 2, 7, -1, 3, 6, 5, 4];

function ThinkingIndicator({ variant }: { variant: NonNullable<AgentThinkingProps['variant']> }) {
  if (variant === 'wave' || variant === 'spin') {
    return <span className="ui-agent-thinking__dots">{Array.from({ length: 9 }, (_, index) => <i key={index} style={{ animationDelay: variant === 'wave' ? `${(Math.floor(index / 3) + index % 3) * 95}ms` : `${orbitOrder[index] * -165}ms` }} />)}</span>;
  }
  if (variant === 'stars') return <span className="ui-agent-thinking__stars">{Array.from({ length: 5 }, (_, index) => <i key={index} style={{ animationDelay: `${index * -320}ms` }} />)}</span>;
  if (variant === 'infinity') return <svg className="ui-agent-thinking__infinity" viewBox="0 0 30 18" fill="none" aria-hidden="true"><path className="ui-agent-thinking__infinity-track" d="M15 9C10 1 1 1 1 9s9 8 14 0c5-8 14-8 14 0s-9 8-14 0" pathLength="100" /><path className="ui-agent-thinking__infinity-head" d="M15 9C10 1 1 1 1 9s9 8 14 0c5-8 14-8 14 0s-9 8-14 0" pathLength="100" /></svg>;
  return <span className="ui-agent-thinking__orb"><i /><i /><i /></span>;
}

export function AgentThinking({ variant = 'wave', label = 'Thinking', active = true, showTimer = true, shimmer = true, tone = 'subtle', className }: AgentThinkingProps) {
  const [elapsed, setElapsed] = useState(0);
  useEffect(() => {
    if (!active || !showTimer) return;
    const start = performance.now();
    const timer = window.setInterval(() => setElapsed((performance.now() - start) / 1000), 100);
    return () => window.clearInterval(timer);
  }, [active, showTimer]);

  return <div className={cx('ui-agent-thinking', className)} data-variant={variant} data-active={active} data-tone={tone} role="status" aria-live="polite"><span className="ui-agent-thinking__indicator" aria-hidden="true"><ThinkingIndicator variant={variant} /></span><span className={cx('ui-agent-thinking__label', shimmer && active && 'ui-agent-thinking__label--shimmer')}>{active ? label : 'Ready'}</span>{active && showTimer && <time aria-hidden="true">{elapsed.toFixed(1)}s</time>}</div>;
}

'use client';

import type { ReactNode, RefObject } from 'react';
import { DropdownPopover } from '@/components/base/dropdown/dropdown';

export type ComposerMenuItem = { id: string; label: string; description?: string; icon?: ReactNode; disabled?: boolean };
export type ComposerMenuGroup = { label: string; items: ComposerMenuItem[] };

type ComposerAddMenuProps = {
  id: string;
  open: boolean;
  anchorRef: RefObject<HTMLButtonElement | null>;
  groups: ComposerMenuGroup[];
  onSelect: (id: string) => void;
  onClose: () => void;
};

export function ComposerAddMenu({ id, open, anchorRef, groups, onSelect, onClose }: ComposerAddMenuProps) {
  const firstEnabledItem = groups.flatMap(group => group.items).find(item => !item.disabled);
  return <DropdownPopover aria-label="Add to message" isOpen={open} onOpenChange={next => { if (!next) onClose(); }} triggerRef={anchorRef} placement="top start" offset={8} className="ui-composer-add-menu">
    <div id={id} role="menu" aria-label="Add to message" className="ui-composer-add-menu__groups">
      {groups.map(group => <section key={group.label} className="ui-composer-add-menu__group">
        <span className="ui-composer-add-menu__heading">{group.label}</span>
        {group.items.map(item => <button key={item.id} data-id={item.id} type="button" role="menuitem" autoFocus={item === firstEnabledItem} disabled={item.disabled} onClick={() => { onSelect(item.id); onClose(); }}>
          <span className="ui-composer-add-menu__icon" aria-hidden="true">{item.icon}</span>
          <span className="ui-composer-add-menu__text"><strong>{item.label}</strong>{item.description && <small>{item.description}</small>}</span>
        </button>)}
      </section>)}
    </div>
  </DropdownPopover>;
}

'use client';

import { forwardRef, useRef } from 'react';
import { AnimatePresence, motion, useIsPresent } from 'motion/react';
import { RiAddLine, RiCloseLine, RiFileLine } from '@remixicon/react';
import { AnimatedHeight } from '@/components/base/animated-height/animated-height';
import { useMediaQuery } from '@/hooks/use-media-query';
import { cx } from '@/utils/cx';

export type ComposerAttachment = { id: string; name: string; thumbnail?: string; progress?: number; status?: 'uploading' | 'ready' | 'error' };
export type ComposerAttachmentsProps = { attachments: ComposerAttachment[]; onAddFiles?: (files: File[]) => void; onRemove?: (id: string) => void; accept?: string; className?: string };

const AttachmentTile = forwardRef<HTMLDivElement, { item: ComposerAttachment; onRemove?: (id: string) => void; reducedMotion: boolean }>(function AttachmentTile({ item, onRemove, reducedMotion }, ref) {
  const present = useIsPresent();
  const progress = typeof item.progress === 'number' ? Math.min(100, Math.max(0, item.progress)) : undefined;
  const uploading = item.status === 'uploading';
  return <motion.div ref={ref} inert={!present} layout={reducedMotion ? false : 'position'} initial={{ opacity: 0, scale: reducedMotion ? 1 : .94 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: reducedMotion ? 1 : .94 }} transition={{ duration: reducedMotion ? 0 : .18, ease: [.2, .8, .2, 1] }} className="ui-composer-attachments__tile" data-status={item.status ?? 'ready'}>
    {item.thumbnail ? <img src={item.thumbnail} alt="" /> : <RiFileLine size={21} aria-hidden />}
    <span title={item.name}>{item.name}</span>
    {progress !== undefined && <svg className="ui-composer-attachments__ring" viewBox="0 0 56 56" aria-hidden="true"><rect x="1.5" y="1.5" width="53" height="53" rx="10" pathLength="100" style={{ strokeDashoffset: 100 - progress }} /></svg>}
    {progress !== undefined && <small data-visible={uploading || undefined}>{Math.round(progress)}%</small>}
    {onRemove && <button type="button" aria-label={`Remove ${item.name}`} disabled={uploading} onClick={() => onRemove(item.id)}><RiCloseLine size={13} aria-hidden /></button>}
  </motion.div>;
});

export function ComposerAttachments({ attachments, onAddFiles, onRemove, accept, className }: ComposerAttachmentsProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const reducedMotion = useMediaQuery('(prefers-reduced-motion: reduce)');
  return <AnimatedHeight className={cx('ui-composer-attachments', className)}>
    <div className="ui-composer-attachments__tiles" data-empty={!attachments.length && !onAddFiles || undefined}>
      <AnimatePresence initial={false} mode="popLayout">{attachments.map(item => <AttachmentTile key={item.id} item={item} onRemove={onRemove} reducedMotion={reducedMotion} />)}</AnimatePresence>
      {onAddFiles && <><input ref={inputRef} className="ui-composer-attachments__input" type="file" multiple accept={accept} aria-label="Add attachments" onChange={event => { onAddFiles(Array.from(event.currentTarget.files ?? [])); event.currentTarget.value = ''; }} /><motion.button layout={reducedMotion ? false : 'position'} transition={{ duration: reducedMotion ? 0 : .18, ease: [.2, .8, .2, 1] }} type="button" className="ui-composer-attachments__add" aria-label="Add attachments" onClick={() => inputRef.current?.click()}><RiAddLine size={19} aria-hidden /></motion.button></>}
    </div>
  </AnimatedHeight>;
}

'use client';

import { useEffect, useId, useState, type CSSProperties } from 'react';
import { RiArrowUpSLine } from '@remixicon/react';
import { Dropdown, DropdownGroup, DropdownItem, DropdownPopover, DropdownTrigger } from '@/components/base/dropdown/dropdown';

export type ComposerModel = { id: string; label: string };
export const composerModels: ComposerModel[] = [
  { id: 'composer', label: 'Composer 2.5' },
  { id: 'sol', label: 'GPT-5.6 Sol' },
  { id: 'fable', label: 'Fable 5' },
  { id: 'sonnet', label: 'Sonnet 5' },
];
const effortNames = ['Minimal', 'Low', 'Medium', 'High', 'Maximum'];

export function ComposerModelPicker({ models, selectedModel, onModelChange, effort, onEffortChange, disabled }: { models: ComposerModel[]; selectedModel?: string; onModelChange: (id: string) => void; effort: number; onEffortChange: (value: number) => void; disabled?: boolean }) {
  const [open, setOpen] = useState(false);
  const effortId = useId();
  useEffect(() => { if (disabled) setOpen(false); }, [disabled]);
  const current = models.find(model => model.id === selectedModel) ?? models[0];
  return <Dropdown isOpen={open} onOpenChange={setOpen}>
    <DropdownTrigger className="ui-composer-model__trigger" aria-label="Model" isDisabled={disabled}><span>{current?.label ?? 'Choose model'}</span><RiArrowUpSLine size={16} aria-hidden /></DropdownTrigger>
    <DropdownPopover aria-label="Model and effort" placement="top start" offset={9} className="ui-composer-model__popover">
      <DropdownGroup label="Models" className="ui-composer-model__models">{models.map(model => <DropdownItem key={model.id} selected={model.id === selectedModel} onSelect={() => onModelChange(model.id)} className="ui-composer-model__option"><span>{model.label}</span><span className="ui-composer-model__radio" aria-hidden /></DropdownItem>)}</DropdownGroup>
      <div className="ui-composer-model__effort"><label htmlFor={effortId}>Effort <strong>{effortNames[effort] ?? 'Medium'}</strong></label><div><span>Faster</span><span>Smarter</span></div><div className="ui-composer-model__range" style={{ '--effort-progress': `${effort * 25}%` } as CSSProperties}><div className="ui-composer-model__ticks" aria-hidden>{effortNames.map(name => <i key={name} />)}</div><input id={effortId} type="range" min="0" max="4" step="1" value={effort} onChange={event => onEffortChange(Number(event.target.value))} aria-valuetext={effortNames[effort]} /></div></div>
    </DropdownPopover>
  </Dropdown>;
}

'use client';

import { useCallback, useEffect, useId, useImperativeHandle, useLayoutEffect, useRef, useState, type KeyboardEvent, type ReactNode, type Ref } from 'react';
import { RiAddLine, RiArrowUpLine, RiAttachmentLine, RiFolder3Line, RiGitBranchLine, RiMicLine } from '@remixicon/react';
import { ComposerAttachments, type ComposerAttachment } from './composer-attachments';
import { ComposerModelPicker, composerModels } from './composer-model-picker';
import { AgentThinking } from '@/components/blocks/agent-thinking/agent-thinking';
import { cx } from '@/utils/cx';
import { ComposerAddMenu, type ComposerMenuGroup } from './composer-add-menu';

export type ComposerProps = { value?: string; defaultValue?: string; onChange?: (value: string) => void; onSend?: (message: string) => void; models?: { id: string; label: string }[]; selectedModel?: string; onModelChange?: (model: string) => void; effort?: number; defaultEffort?: number; onEffortChange?: (effort: number) => void; onVoice?: () => void; attachments?: ComposerAttachment[]; onAddFiles?: (files: File[]) => void; onRemoveAttachment?: (id: string) => void; menuGroups?: ComposerMenuGroup[]; onMenuAction?: (id: string) => void; branch?: string; project?: string; agentLabel?: string; contextPercent?: number; isWorking?: boolean; placeholder?: string; footerStart?: ReactNode; modelPicker?: ReactNode; status?: ReactNode; disabled?: boolean; inputRef?: Ref<HTMLTextAreaElement>; maxInputHeight?: number; statusPlacement?: 'bottom' | 'tab'; className?: string };
const defaultMenuGroups: ComposerMenuGroup[] = [{ label: 'Add', items: [{ id: 'files', label: 'Files and folders', icon: <RiAttachmentLine size={18} /> }] }];
export function Composer({ value, defaultValue = '', onChange, onSend, models = composerModels, selectedModel, onModelChange, effort, defaultEffort = 2, onEffortChange, onVoice, attachments = [], onAddFiles, onRemoveAttachment, menuGroups = defaultMenuGroups, onMenuAction, branch, project, agentLabel, contextPercent, isWorking = false, placeholder = 'Ask me anything', footerStart, modelPicker, status: statusSlot, disabled = false, inputRef: forwardedInputRef, maxInputHeight = 120, statusPlacement = 'bottom', className }: ComposerProps) {
  const [internal, setInternal] = useState(defaultValue);
  const [internalModel, setInternalModel] = useState(() => models.find(model => model.id === 'fable')?.id ?? models[0]?.id);
  const [internalEffort, setInternalEffort] = useState(defaultEffort);
  const [internalAttachments, setInternalAttachments] = useState<ComposerAttachment[]>([]);
  const [menuOpen, setMenuOpen] = useState(false);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const inputMeasured = useRef(false);
  const fileRef = useRef<HTMLInputElement>(null);
  const addRef = useRef<HTMLButtonElement>(null);
  const menuId = useId();
  const closeMenu = useCallback(() => setMenuOpen(false), []);
  useEffect(() => { if (isWorking || disabled) setMenuOpen(false); }, [isWorking, disabled]);
  const text = value ?? internal;
  const busy = disabled || isWorking;
  useImperativeHandle(forwardedInputRef, () => inputRef.current!, []);
  const resizeInput = useCallback(() => {
    const input = inputRef.current;
    if (!input) return;
    const previousHeight = input.offsetHeight;
    // Measure natural content without animating through an intermediate auto size.
    // Restoring the current rendered height also makes rapid edits reverse smoothly.
    input.style.transition = 'none';
    input.style.height = 'auto';
    const naturalHeight = input.scrollHeight;
    const targetHeight = Math.min(naturalHeight, maxInputHeight);
    input.style.overflowY = naturalHeight > maxInputHeight ? 'auto' : 'hidden';
    input.style.height = `${inputMeasured.current ? previousHeight : targetHeight}px`;
    void input.offsetHeight;
    input.style.removeProperty('transition');
    input.style.height = `${targetHeight}px`;
    inputMeasured.current = true;
  }, [maxInputHeight]);
  useLayoutEffect(resizeInput, [text, resizeInput]);
  useLayoutEffect(() => {
    const input = inputRef.current;
    if (!input) return;
    let width = input.clientWidth;
    const observer = new ResizeObserver(() => { if (input.clientWidth !== width) { width = input.clientWidth; resizeInput(); } });
    observer.observe(input);
    return () => observer.disconnect();
  }, [resizeInput]);
  const modelKey = models.some(model => model.id === (selectedModel ?? internalModel)) ? selectedModel ?? internalModel : models[0]?.id;
  const items = attachments.length ? attachments : internalAttachments;
  function update(next: string) { if (value === undefined) setInternal(next); onChange?.(next); }
  function send() { const trimmed = text.trim(); if (!trimmed || busy) return; onSend?.(trimmed); update(''); }
  function addFiles(files: File[]) { if (!files.length) return; if (onAddFiles) onAddFiles(files); else setInternalAttachments(current => [...current, ...files.map(file => ({ id: `${file.name}-${file.lastModified}`, name: file.name, status: 'ready' as const }))]); }
  function remove(id: string) { if (onRemoveAttachment) onRemoveAttachment(id); else setInternalAttachments(current => current.filter(item => item.id !== id)); }
  function onKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) { if (event.key === 'Enter' && !event.shiftKey && !event.nativeEvent.isComposing) { event.preventDefault(); send(); } }
  function chooseMenuItem(id: string) { if (id === 'files') fileRef.current?.click(); else onMenuAction?.(id); }
  const status = statusSlot !== undefined ? statusSlot : (branch || project || agentLabel || contextPercent !== undefined) && <div className="ui-composer__status">{branch && <span><RiGitBranchLine size={13} aria-hidden />{branch}</span>}{project && <span><RiFolder3Line size={13} aria-hidden />{project}</span>}<span className="ui-composer__status-spacer" />{agentLabel && <span>{agentLabel}</span>}{contextPercent !== undefined && <span className="ui-composer__context">◕ {Math.round(contextPercent)}%</span>}</div>;
  return <div className={cx('ui-composer', className)} data-working={isWorking || undefined} data-status-placement={statusPlacement}>
    {isWorking && <div className="ui-composer__thinking"><AgentThinking label="Working" /></div>}
    {statusPlacement === 'tab' && status}
    <input ref={fileRef} className="ui-composer-attachments__input" type="file" multiple disabled={busy} aria-label="Attach files" onChange={event => { addFiles(Array.from(event.currentTarget.files ?? [])); event.currentTarget.value = ''; }} />
    <div className="ui-composer__panel">
      <ComposerAttachments attachments={items} onRemove={remove} />
      <div className="ui-composer__entry">
        <button ref={addRef} type="button" className="ui-composer__add" aria-label={menuOpen ? 'Close add menu' : 'Add attachment'} aria-haspopup="menu" aria-controls={menuId} aria-expanded={menuOpen} disabled={busy} onClick={() => setMenuOpen(open => !open)}><RiAddLine size={18} aria-hidden /></button>
        <textarea ref={inputRef} rows={1} value={text} placeholder={placeholder} aria-label="Message" onChange={event => update(event.target.value)} style={{ maxHeight: maxInputHeight }} onKeyDown={onKeyDown} />
        <div className="ui-composer__footer">
          {footerStart}<span className="ui-composer__footer-spacer" />
          {modelPicker !== undefined ? modelPicker : <ComposerModelPicker models={models} selectedModel={modelKey} onModelChange={key => { if (selectedModel === undefined) setInternalModel(key); onModelChange?.(key); }} effort={effort ?? internalEffort} onEffortChange={next => { if (effort === undefined) setInternalEffort(next); onEffortChange?.(next); }} disabled={busy} />}
          <button type="button" className="ui-composer__voice" aria-label="Voice input" onClick={onVoice} disabled={!onVoice || busy}><RiMicLine size={18} aria-hidden /></button>
          <button type="button" className="ui-composer__send" aria-label="Send message" disabled={!text.trim() || busy} onClick={send}><RiArrowUpLine size={20} aria-hidden /></button>
        </div>
      </div>
    </div>
    {statusPlacement === 'bottom' && status}
    <ComposerAddMenu id={menuId} open={menuOpen && !busy} anchorRef={addRef} groups={menuGroups} onSelect={chooseMenuItem} onClose={closeMenu} />
  </div>;
}

